    RdmaMessage msg = m_messages.front();
    m_messages.pop();
    msg.m_notifyAppFinish(this,msg.send_wr);
    while(!m_messages.empty() && m_messages.front().send_wr.total_length == 0) {
      msg = m_messages.front();
      m_messages.pop();
      msg.m_notifyAppFinish(this,msg.send_wr);

    return true;
  }
